import { createAdminClient, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { syncFinancesJob } from '../_shared/amazon/finances.ts';

function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});}

Deno.serve(async(req:Request)=>{
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    requireInternalSecret(req);
    const body=await req.json().catch(()=>({}));
    if(!body?.job)return response({error:'Falta el job financiero.'},400);
    const rowsProcessed=await syncFinancesJob(createAdminClient(),body.job);
    return response({ok:true,rowsProcessed});
  }catch(error){return response({error:error instanceof Error?error.message:'No se pudieron sincronizar las finanzas Amazon.'},500);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import { spApiRequest } from './sp-api.ts';
import { loadAmazonSpApiCredentials } from './config.ts';
import { normalizeFinanceComponents } from './finance-components.ts';

const SAFE_LAG_MS=2*60*1000;

type Currency={currencyAmount?:string|number|null;currencyCode?:string|null}|null|undefined;
function money(value:Currency){const parsed=Number(value?.currencyAmount);return Number.isFinite(parsed)?parsed:0;}
function currency(value:Currency){return value?.currencyCode?String(value.currencyCode):'EUR';}
function safePostedBefore(value:string|undefined|null){const limit=new Date(Date.now()-SAFE_LAG_MS);if(!value)return limit.toISOString();const requested=new Date(value);return (requested<limit?requested:limit).toISOString();}
function identifierName(item:any){return String(item?.relatedIdentifierName||item?.name||item?.type||'').trim();}
function identifierValue(item:any){return String(item?.relatedIdentifierValue||item?.value||item?.id||'').trim();}
function safeIdentifiers(transaction:any){return (Array.isArray(transaction?.relatedIdentifiers)?transaction.relatedIdentifiers:[]).map((item:any)=>({name:identifierName(item),value:identifierValue(item)})).filter((item:any)=>item.name&&item.value).slice(0,50);}
function identifier(transaction:any,pattern:RegExp){const found=safeIdentifiers(transaction).find((item:any)=>pattern.test(item.name));return found?.value||null;}
function collectBreakdownTypes(value:any,out:string[]=[]){if(!value||typeof value!=='object')return out;if(typeof value.breakdownType==='string')out.push(value.breakdownType);const nested=Array.isArray(value.breakdowns)?value.breakdowns:[];for(const child of nested)collectBreakdownTypes(child,out);return out;}
function sanitizeBreakdowns(value:any):any[]{const source=Array.isArray(value)?value:[];return source.slice(0,100).map((entry:any)=>({breakdownType:String(entry?.breakdownType||''),breakdownAmount:entry?.breakdownAmount?{currencyAmount:money(entry.breakdownAmount),currencyCode:currency(entry.breakdownAmount)}:null,breakdowns:sanitizeBreakdowns(entry?.breakdowns)}));}
export function safeTransactionMetadata(transaction:any){return {marketplaceId:transaction?.marketplaceDetails?.marketplaceId?String(transaction.marketplaceDetails.marketplaceId):null,breakdowns:sanitizeBreakdowns(transaction?.breakdowns)};}
function firstProductContext(transaction:any){const candidates:any[]=[];if(Array.isArray(transaction?.contexts))candidates.push(...transaction.contexts);for(const item of Array.isArray(transaction?.items)?transaction.items:[]){if(Array.isArray(item?.contexts))candidates.push(...item.contexts);}return candidates.find(context=>context&&(context.sku||context.asin))||null;}
export function categorizeTransaction(transaction:any){const breakdownText=collectBreakdownTypes(transaction).join(' ');const text=`${transaction?.transactionType||''} ${transaction?.description||''} ${breakdownText}`.toLowerCase();if(/refund|chargeback|return/.test(text))return 'refund';if(/referral/.test(text))return 'referral_fee';if(/storage/.test(text))return 'storage_fee';if(/fba|fulfil+l?ment|fulfillment/.test(text)&&/fee|expense|charge/.test(text))return 'fba_fee';if(/\btax\b|\bvat\b|impuesto/.test(text))return 'tax';if(/adjust|reimburse|reimbursement|correction/.test(text))return 'adjustment';if(/fee|expense|charge|commission/.test(text))return 'other_fee';if(/sale|shipment|order payment|product charges|proceeds/.test(text))return 'sale';return 'other';}
function stableTransactionSeed(transaction:any,job:any){return JSON.stringify({marketplaceId:transaction?.marketplaceDetails?.marketplaceId||job?.marketplace_id||null,transactionType:transaction?.transactionType||null,transactionStatus:transaction?.transactionStatus||null,postedDate:transaction?.postedDate||null,amount:money(transaction?.totalAmount),currency:currency(transaction?.totalAmount),related:safeIdentifiers(transaction).sort((a:any,b:any)=>`${a.name}:${a.value}`.localeCompare(`${b.name}:${b.value}`))});}
export async function deriveTransactionKey(transaction:any,job:any){const explicit=String(transaction?.transactionId||'').trim();if(explicit)return `id:${explicit}`;const bytes=new TextEncoder().encode(stableTransactionSeed(transaction,job));const digest=await crypto.subtle.digest('SHA-256',bytes);return `sha256:${Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('')}`;}
async function normalizeTransaction(transaction:any,job:any){const product=firstProductContext(transaction);const total=transaction?.totalAmount||null;return {owner_id:job.owner_id,amazon_account_id:job.amazon_account_id,transaction_key:await deriveTransactionKey(transaction,job),amazon_transaction_id:transaction?.transactionId?String(transaction.transactionId):null,marketplace_id:transaction?.marketplaceDetails?.marketplaceId?String(transaction.marketplaceDetails.marketplaceId):job.marketplace_id||null,amazon_order_id:identifier(transaction,/order/i),seller_sku:product?.sku?String(product.sku):null,asin:product?.asin?String(product.asin):null,posted_date:transaction?.postedDate||null,transaction_status:transaction?.transactionStatus?String(transaction.transactionStatus):null,transaction_type:String(transaction?.transactionType||'UNKNOWN'),category:categorizeTransaction(transaction),amount_original:money(total),currency_code:currency(total),amount_eur:null,fx_rate:null,related_identifiers:safeIdentifiers(transaction),metadata:safeTransactionMetadata(transaction),synced_at:new Date().toISOString(),updated_at:new Date().toISOString()};}

/** One atomic database transaction per SP-API page. Unchanged rows retain IDs/timestamps.
 * The RPC owns amazon_finance_transactions conflict identity: owner_id,amazon_account_id,transaction_key.
 */
export async function upsertTransactions(admin:any,transactions:any[],job:any){
  const entries=new Map<string,{transaction:any;original:any}>();
  for(const original of transactions){const transaction=await normalizeTransaction(original,job);entries.set(transaction.transaction_key,{transaction,original});}
  if(!entries.size)return 0;
  const page:any[]=[];
  for(const {transaction,original} of entries.values()){
    const normalized=await normalizeFinanceComponents(original,transaction,job);
    const components=normalized.map(({finance_transaction_id,...component})=>component);
    page.push({transaction,components});
  }
  const {error}=await admin.rpc('amazon_replace_finance_page',{p_owner_id:job.owner_id,p_amazon_account_id:job.amazon_account_id,p_page:page});
  if(error)throw error;
  return page.length;
}

export async function syncFinancesJob(admin:any,job:any){
  if(!job?.window_from)throw new Error('Job de finanzas incompleto.');const postedBefore=safePostedBefore(job.window_to);if(new Date(job.window_from)>=new Date(postedBefore))return 0;const credentials=await loadAmazonSpApiCredentials(admin,{amazonAccountId:job.amazon_account_id,ownerId:job.owner_id});let nextToken:string|undefined;let processed=0;
  do{const query:any={postedAfter:job.window_from,postedBefore,...(job.marketplace_id?{marketplaceId:job.marketplace_id}:{}),...(nextToken?{nextToken}:{})};const data:any=await spApiRequest('/finances/2024-06-19/transactions',{query},credentials);const payload=data?.payload||data||{};const transactions=Array.isArray(payload?.transactions)?payload.transactions:[];processed+=await upsertTransactions(admin,transactions,job);nextToken=payload?.nextToken||undefined;}while(nextToken);
  return processed;
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}

export type FinanceComponentCategory =
  | 'refund'
  | 'commission_fee'
  | 'fba_fee'
  | 'digital_services_fee'
  | 'storage_fee'
  | 'other_amazon_fee'
  | 'adjustment'
  | 'ads_payment_excluded'
  | 'sale_audit'
  | 'tax_audit';

type CurrencyAmount={currencyAmount?:string|number|null;currencyCode?:string|null}|null|undefined;
type Breakdown={breakdownType?:string|null;breakdownAmount?:CurrencyAmount;breakdowns?:Breakdown[]|null};
type EconomicNode={node:Breakdown;path:string[];category:FinanceComponentCategory;componentType:string;tax:number|null;taxCurrency:string|null};

export type FinanceComponentInput={
  owner_id:string;amazon_account_id:string;finance_transaction_id:string;marketplace_id:string|null;amazon_order_id:string|null;
  seller_sku:string|null;asin:string|null;posted_date:string|null;component_key:string;component_type:string;
  component_category:FinanceComponentCategory;amount_original:number;currency_code:string;tax_amount_original:number|null;
  amount_eur:null;tax_amount_eur:null;fx_rate:null;updated_at:string;
};

const BASE_TYPE='Base';
const TAX_TYPE='Tax';
function number(value:unknown){const n=Number(value);return Number.isFinite(n)?n:0;}
function amount(node:Breakdown){return number(node?.breakdownAmount?.currencyAmount);}
function currency(node:Breakdown){return String(node?.breakdownAmount?.currencyCode||'EUR').toUpperCase();}
function children(node:Breakdown){return Array.isArray(node?.breakdowns)?node.breakdowns:[];}
function type(node:Breakdown){return String(node?.breakdownType||'').trim();}
function lower(value:string){return value.trim().toLowerCase();}

function classify(name:string):FinanceComponentCategory|null{
  const text=lower(name);
  if(/productadspayment|advertis|sponsored/.test(text))return 'ads_payment_excluded';
  if(/reservedebit|reservecredit|microdeposit/.test(text))return 'sale_audit';
  if(/returnpostagebilling_vat/.test(text))return 'tax_audit';
  if(/returnpostagebilling_postage/.test(text))return 'other_amazon_fee';
  if(text==='refunded sales'||text==='refundedsales')return 'refund';
  if(/commission|referral/.test(text))return 'commission_fee';
  if(/fbaperunitfulfillmentfee|fulfil+l?ment.*fee|fba.*fee/.test(text))return 'fba_fee';
  if(/digitalservicesfee|digital services fee/.test(text))return 'digital_services_fee';
  if(/storage/.test(text))return 'storage_fee';
  if(/clawback|adjust|reimburse|correction/.test(text))return 'adjustment';
  if(text==='productcharges'||text==='product charges')return 'sale_audit';
  if(text===lower(TAX_TYPE))return 'tax_audit';
  if(/amazonfees|amazon fees|fee|expense|charge/.test(text))return 'other_amazon_fee';
  return null;
}

function refundedSalesNode(node:Breakdown,path:string[]):EconomicNode{
  const nested=children(node);const product=nested.find(child=>/product\s*charges/i.test(type(child)));const tax=nested.find(child=>lower(type(child))===lower(TAX_TYPE));const source=product||node;
  return {node:source,path,category:'refund',componentType:'Refunded Sales',tax:tax?amount(tax):null,taxCurrency:tax?currency(tax):null};
}

function economicNodes(nodes:Breakdown[],path:string[]=[]):EconomicNode[]{
  const out:EconomicNode[]=[];
  for(let index=0;index<nodes.length;index+=1){
    const node=nodes[index];const nodeType=type(node);const nodePath=[...path,`${index}:${nodeType}`];const nested=children(node);
    if(/refunded\s*sales/i.test(nodeType)){out.push(refundedSalesNode(node,nodePath));continue;}
    const base=nested.find(child=>lower(type(child))===lower(BASE_TYPE));const tax=nested.find(child=>lower(type(child))===lower(TAX_TYPE));const category=classify(nodeType);
    if(category&&base){out.push({node:base,path:nodePath,category,componentType:nodeType,tax:tax?amount(tax):null,taxCurrency:tax?currency(tax):null});continue;}
    if(category&&nested.length===0){out.push({node,path:nodePath,category,componentType:nodeType,tax:null,taxCurrency:null});continue;}
    out.push(...economicNodes(nested,nodePath));
  }
  return out;
}

async function sha256(value:string){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('');}
function rawBreakdowns(transaction:any):Breakdown[]{return Array.isArray(transaction?.breakdowns)?transaction.breakdowns:[];}

function syntheticAdsNode(transaction:any):EconomicNode|null{
  const transactionType=String(transaction?.transactionType||'');if(!/productadspayment|advertis|sponsored/i.test(transactionType))return null;const total=transaction?.totalAmount||null;
  return {node:{breakdownType:transactionType,breakdownAmount:total},path:[`transaction:${transactionType}`],category:'ads_payment_excluded',componentType:transactionType,tax:null,taxCurrency:null};
}

function persistedCategory(value:unknown):FinanceComponentCategory|null{
  const category=lower(String(value||''));
  if(category==='refund')return 'refund';
  if(category==='referral_fee')return 'commission_fee';
  if(category==='fba_fee')return 'fba_fee';
  if(category==='storage_fee')return 'storage_fee';
  if(category==='adjustment')return 'adjustment';
  if(category==='other_fee')return 'other_amazon_fee';
  if(category==='sale')return 'sale_audit';
  if(category==='tax')return 'tax_audit';
  return null;
}

function syntheticFallbackNode(transaction:any,persistedTransaction:any):EconomicNode|null{
  const totalAmount=number(transaction?.totalAmount?.currencyAmount??persistedTransaction?.amount_original);
  if(totalAmount===0)return null;
  const fallbackCategory=persistedCategory(persistedTransaction?.category);
  if(!fallbackCategory)return null;
  const transactionType=String(persistedTransaction?.transaction_type||transaction?.transactionType||'Transaction');
  const currencyCode=String(transaction?.totalAmount?.currencyCode||persistedTransaction?.currency_code||'EUR').toUpperCase();
  return {
    node:{breakdownType:transactionType,breakdownAmount:{currencyAmount:totalAmount,currencyCode}},
    path:[`transaction-fallback:${transactionType}`],
    category:fallbackCategory,
    componentType:`${transactionType} (fallback)`,
    tax:null,
    taxCurrency:null,
  };
}

export async function normalizeFinanceComponents(transaction:any,persistedTransaction:any,_job:any):Promise<FinanceComponentInput[]>{
  const nodes=economicNodes(rawBreakdowns(transaction));
  if(!nodes.length){const synthetic=syntheticAdsNode(transaction);if(synthetic)nodes.push(synthetic);}
  if(!nodes.length){const fallback=syntheticFallbackNode(transaction,persistedTransaction);if(fallback)nodes.push(fallback);}

  const now=new Date().toISOString();const result:FinanceComponentInput[]=[];
  for(const entry of nodes){
    const componentKey=await sha256(JSON.stringify({transactionKey:persistedTransaction.transaction_key||persistedTransaction.id,path:entry.path,category:entry.category,componentType:entry.componentType}));
    result.push({
      owner_id:String(persistedTransaction.owner_id),amazon_account_id:String(persistedTransaction.amazon_account_id),finance_transaction_id:String(persistedTransaction.id),
      marketplace_id:persistedTransaction.marketplace_id?String(persistedTransaction.marketplace_id):null,amazon_order_id:persistedTransaction.amazon_order_id?String(persistedTransaction.amazon_order_id):null,
      seller_sku:persistedTransaction.seller_sku?String(persistedTransaction.seller_sku):null,asin:persistedTransaction.asin?String(persistedTransaction.asin):null,
      posted_date:persistedTransaction.posted_date?String(persistedTransaction.posted_date):null,component_key:componentKey,component_type:entry.componentType,
      component_category:entry.category,
      // Persist the normalized component as gross amount plus its tax share.
      // amazon_finance_transactions.metadata keeps Amazon's original payload for audit.
      amount_original:amount(entry.node)+(entry.tax!==null&&(!entry.taxCurrency||entry.taxCurrency===currency(entry.node))?entry.tax:0),
      currency_code:currency(entry.node),tax_amount_original:entry.tax,
      amount_eur:null,tax_amount_eur:null,fx_rate:null,updated_at:now,
    });
  }
  return result;
}
